<?php
namespace App\Http\Controllers\PublicSite;
use App\Http\Controllers\Controller; use App\Models\{PropertyWebSetting,RoomType,BookingAddon,Promotion};
class HotelWebsiteController extends Controller { public function home(?string $slug=null){$web=$slug?PropertyWebSetting::where('slug',$slug)->firstOrFail():PropertyWebSetting::with('property')->firstOrFail();$web->load('property');$types=RoomType::where('property_id',$web->property_id)->where('is_active',1)->orderBy('base_rate')->get();$promos=Promotion::where('property_id',$web->property_id)->where('is_active',1)->where(function($q){$q->whereNull('starts_at')->orWhere('starts_at','<=',now());})->where(function($q){$q->whereNull('ends_at')->orWhere('ends_at','>=',now());})->limit(4)->get();return view('public.home',compact('web','types','promos'));} public function booking(string $slug){$web=PropertyWebSetting::where('slug',$slug)->with('property')->firstOrFail();abort_unless($web->online_booking_enabled,404);$types=RoomType::where('property_id',$web->property_id)->where('is_active',1)->get();$addons=BookingAddon::where('property_id',$web->property_id)->where('is_active',1)->get();return view('public.booking',compact('web','types','addons'));} }
